package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

type UserService struct {
	users map[string]User
	mutex sync.RWMutex
}

func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

func (s *UserService) CreateUser(u User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	// Generate a new UUID for the user
	u.ID = uuid.New().String()
	s.users[u.ID] = u
	return u, nil
}

func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"experiment/internal/service"
)

type UserHandlers struct {
	service *service.UserService
}

func NewUserHandlers(s *service.UserService) *UserHandlers {
	return &UserHandlers{service: s}
}

func (h *UserHandlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetAllUsers(w, r)
	case http.MethodPost:
		h.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]

	switch r.Method {
	case http.MethodGet:
		h.GetUserByID(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandlers) GetAllUsers(w http.ResponseWriter, r *http.Request) {
	users := h.service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

func (h *UserHandlers) CreateUser(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.service.CreateUser(u)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

func (h *UserHandlers) GetUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	u, ok := h.service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	// Initialize the user service
	userService := service.NewUserService()

	// Initialize the user handlers with the user service
	handlers := api.NewUserHandlers(userService)

	// Register HTTP handlers
	http.HandleFunc("/users", handlers.HandleUsers)
	http.HandleFunc("/users/", handlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"experiment/internal/service"
	"testing"

	"github.com/google/uuid"
)

func TestUserService_CreateUser(t *testing.T) {
	s := service.NewUserService()

	user := service.User{Name: "Test User", Email: "test@example.com"}
	createdUser, err := s.CreateUser(user)

	if err != nil {
		t.Fatalf("expected no error, got %v", err)
	}

	if createdUser.ID == "" {
		t.Error("expected user ID to be generated, got empty")
	}

	if _, err := uuid.Parse(createdUser.ID); err != nil {
		t.Errorf("expected a valid UUID, got %v", createdUser.ID)
	}

	if createdUser.Name != user.Name {
		t.Errorf("expected user name %s, got %s", user.Name, createdUser.Name)
	}

	if createdUser.Email != user.Email {
		t.Errorf("expected user email %s, got %s", user.Email, createdUser.Email)
	}
}

func TestUserService_GetAllUsers(t *testing.T) {
	s := service.NewUserService()

	user1 := service.User{Name: "User 1", Email: "user1@example.com"}
	user2 := service.User{Name: "User 2", Email: "user2@example.com"}

	s.CreateUser(user1)
	s.CreateUser(user2)

	allUsers := s.GetAllUsers()

	if len(allUsers) != 2 {
		t.Errorf("expected 2 users, got %d", len(allUsers))
	}
}

func TestUserService_GetUserByID(t *testing.T) {
	s := service.NewUserService()

	user := service.User{Name: "Test User", Email: "test@example.com"}
	createdUser, _ := s.CreateUser(user)

	foundUser, ok := s.GetUserByID(createdUser.ID)

	if !ok {
		t.Error("expected to find user, but got not found")
	}

	if foundUser.ID != createdUser.ID {
		t.Errorf("expected user ID %s, got %s", createdUser.ID, foundUser.ID)
	}

	_, ok = s.GetUserByID("nonexistent-id")
	if ok {
		t.Error("expected not to find user, but found one")
	}
}

package api_test

import (
	"bytes"
	"encoding/json"
	"experiment/internal/api"
	"experiment/internal/service"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestUserHandlers_GetAllUsers(t *testing.T) {
	svc := service.NewUserService()
	handlers := api.NewUserHandlers(svc)

	// Add some dummy users
	svc.CreateUser(service.User{Name: "Alice", Email: "alice@example.com"})
	svc.CreateUser(service.User{Name: "Bob", Email: "bob@example.com"})

	req, err := http.NewRequest(http.MethodGet, "/users", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handlers.GetAllUsers(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	expected := `[{"ID":"`
	if !bytes.Contains(rr.Body.Bytes(), []byte(expected)) {
		t.Errorf("handler returned unexpected body: got %v want containing %v",
			rr.Body.String(), expected)
	}

	var users []service.User
	if err := json.NewDecoder(rr.Body).Decode(&users); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if len(users) != 2 {
		t.Errorf("expected 2 users, got %d", len(users))
	}
}

func TestUserHandlers_CreateUser(t *testing.T) {
	svc := service.NewUserService()
	handlers := api.NewUserHandlers(svc)

	user := service.User{Name: "Charlie", Email: "charlie@example.com"}
	jsonUser, _ := json.Marshal(user)

	req, err := http.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(jsonUser))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", "application/json")

	rr := httptest.NewRecorder()
	handlers.CreateUser(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusCreated)
	}

	var createdUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&createdUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if createdUser.ID == "" {
		t.Error("expected user ID to be generated, got empty")
	}
	if createdUser.Name != user.Name {
		t.Errorf("expected user name %s, got %s", user.Name, createdUser.Name)
	}
}

func TestUserHandlers_GetUserByID(t *testing.T) {
	svc := service.NewUserService()
	handlers := api.NewUserHandlers(svc)

	user := service.User{Name: "David", Email: "david@example.com"}
	createdUser, _ := svc.CreateUser(user)

	req, err := http.NewRequest(http.MethodGet, "/users/"+createdUser.ID, nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handlers.GetUserByID(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	var foundUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&foundUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if foundUser.ID != createdUser.ID {
		t.Errorf("expected user ID %s, got %s", createdUser.ID, foundUser.ID)
	}
}
